/**
 * Typed access to the baked catalog (generated by scripts/build-catalog.ts
 * from the comparemypeps / longevity-signal snapshot).
 *
 * Regenerate after a data refresh:
 *   node --experimental-strip-types scripts/build-catalog.ts
 */
import catalogJson from "./catalog.json";

export interface CatalogProduct {
  id: number;
  compound: string;
  category: string | null;
  size: string;
  mg: number | null;
  form: string | null;
  price: number | null;
  regularPrice: number | null;
  onSale: boolean;
  discountPct: number | null;
  inStock: boolean;
  currency: string;
  url: string;
  observedAt: string | null;
}

export interface CatalogVendor {
  slug: string;
  name: string;
  website: string;
  affiliateUrl: string;
  code: string | null;
  savings: string;
  savingsPct: number | null;
  order: number;
  region?: string;
  comingSoon?: boolean;
  houseBrand?: boolean;
  productCount: number;
  onSaleCount: number;
  cheapest: number | null;
  products: CatalogProduct[];
}

export interface SalePick {
  vendorSlug: string;
  vendorName: string;
  code: string | null;
  product: CatalogProduct;
}

export interface Catalog {
  generatedAt: string;
  bakedAt: string;
  vendorCount: number;
  productCount: number;
  saleOfWeek: SalePick | null;
  topDeals: SalePick[];
  vendors: CatalogVendor[];
}

export const CATALOG = catalogJson as unknown as Catalog;

export const VENDORS = CATALOG.vendors;

export function getVendor(slug: string): CatalogVendor | undefined {
  return CATALOG.vendors.find((v) => v.slug === slug);
}

export function hostOf(url: string): string {
  try {
    return new URL(url).hostname.replace(/^www\./, "");
  } catch {
    return "";
  }
}

export function formatPrice(
  value: number | null,
  currency = "USD",
): string {
  if (value === null || value === undefined) return "—";
  try {
    return new Intl.NumberFormat("en-US", {
      style: "currency",
      currency,
      maximumFractionDigits: value % 1 === 0 ? 0 : 2,
    }).format(value);
  } catch {
    return `$${value}`;
  }
}
